//! `facade/manifest.json` (Phase 1 T4) → [`SystemWorkerRef`] +
//! [`FacadeRefs`] for [`crate::capnp::render_tenant_config`].
//!
//! The manifest is generated by `facade/tools/gen-manifest.mjs` and records,
//! per system worker, the closed set of ES modules (repo-relative logical
//! names, `.ts` sources addressed by sha256) plus the exported entrypoint
//! class and whether the worker needs the `BINDING_BACKEND` binding. This
//! parser is the typed boundary: anything outside the emitted shape fails
//! closed before it can reach capnp rendering.

use std::collections::BTreeMap;

use serde::Deserialize;

use crate::capnp::{
    is_lower_hex, valid_entrypoint, valid_service_name, FacadeRefs, ServiceEndpoint,
    SystemModuleRef, SystemWorkerRef,
};
use crate::error::ConfigError;
use crate::manifest::valid_module_name;

/// `schemaVersion` accepted by this parser. Version 2 addresses published
/// dist bytes (`sha256` over `facade/dist/**`); version 1 addressed
/// TypeScript sources workerd could never load.
pub const FACADE_MANIFEST_SCHEMA_VERSION: u32 = 2;

/// Service names whose endpoints fill [`FacadeRefs`].
const REQUIRED_FACADES: [&str; 7] = [
    "facade-kv",
    "facade-r2",
    "facade-assets",
    "facade-pg",
    "facade-d1",
    "facade-queue",
    "facade-ratelimit",
];

/// Service name of the T6 egress worker — required since T6: it is the
/// `globalOutbound` target for every tenant worker.
pub const EGRESS_SERVICE: &str = "vrt-egress";

/// Service name of the deny-all worker — required since T6 review: the
/// `globalOutbound` target for every non-egress system worker (facades
/// must never reach a network).
pub const DENY_OUTBOUND_SERVICE: &str = "vrt-no-network";

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
#[serde(rename_all = "camelCase")]
struct WireManifest {
    schema_version: u32,
    generated_by: String,
    /// Node major version that produced `dist/`; the transpile output is
    /// only guaranteed deterministic within one major, so it is recorded.
    node_version: String,
    #[serde(default)]
    externals: BTreeMap<String, String>,
    workers: BTreeMap<String, WireWorker>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
#[serde(rename_all = "camelCase")]
struct WireWorker {
    entrypoint: String,
    needs_binding_backend: bool,
    main_module: String,
    modules: Vec<WireModule>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct WireModule {
    /// Logical specifier-resolvable name (`.js`), embedded under this key.
    name: String,
    /// Repo-relative path of the published bytes inside `facade/dist/`.
    dist: String,
    /// Repo-relative TypeScript source (provenance only, never embedded).
    source: String,
    /// sha256 of the source file (provenance only).
    #[serde(rename = "sourceSha256")]
    source_sha256: String,
    /// sha256 of the dist bytes — what `sys/<digest>` embeds.
    sha256: String,
}

/// Parsed facade manifest: the four product endpoints plus the egress
/// endpoint plus every declared system worker, sorted by service name
/// for deterministic rendering.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FacadeManifest {
    /// Endpoints for `kv` / `r2` / `assets` / `pg` tenant bindings.
    pub facades: FacadeRefs,
    /// The `vrt-egress` endpoint — `globalOutbound` target for tenants.
    pub egress: ServiceEndpoint,
    /// The `vrt-no-network` endpoint — deny-all `globalOutbound` target
    /// for non-egress system workers.
    pub deny_outbound: ServiceEndpoint,
    /// All system workers declared in the manifest (service-name order).
    pub system_workers: Vec<SystemWorkerRef>,
}

fn check_text(value: &str, max: usize, field: &'static str) -> Result<(), ConfigError> {
    if value.is_empty()
        || value.len() > max
        || !value
            .bytes()
            .all(|b| (0x20..=0x7e).contains(&b) || b >= 0x80)
    {
        return Err(ConfigError::Identifier(field));
    }
    Ok(())
}

/// Parse and validate a `facade/manifest.json` document.
///
/// Fail closed on: wrong schema version, malformed identifiers, a worker
/// missing required fields, `mainModule` absent from `modules`, duplicate
/// module names, a non-64-hex digest, an unbounded `source`, or any of the
/// four required facade services or `vrt-egress` being absent.
pub fn parse_facade_manifest(json: &str) -> Result<FacadeManifest, ConfigError> {
    let wire: WireManifest =
        serde_json::from_str(json).map_err(|_| ConfigError::Identifier("systemManifest"))?;
    if wire.schema_version != FACADE_MANIFEST_SCHEMA_VERSION {
        return Err(ConfigError::Identifier("systemManifest.schemaVersion"));
    }
    check_text(&wire.generated_by, 256, "systemManifest.generatedBy")?;
    check_text(&wire.node_version, 16, "systemManifest.nodeVersion")?;
    if wire.externals.len() > 64
        || wire
            .externals
            .iter()
            .any(|(k, v)| k.len() > 256 || v.len() > 256)
    {
        return Err(ConfigError::Capacity("systemManifest.externals"));
    }

    let mut system_workers = Vec::with_capacity(wire.workers.len());
    for (service_name, worker) in &wire.workers {
        if !valid_service_name(service_name) {
            return Err(ConfigError::Identifier("workers.serviceName"));
        }
        if !valid_entrypoint(&worker.entrypoint) {
            return Err(ConfigError::Identifier("workers.entrypoint"));
        }
        if !valid_module_name(&worker.main_module) {
            return Err(ConfigError::Identifier("workers.mainModule"));
        }
        if worker.modules.is_empty() || worker.modules.len() > 1024 {
            return Err(ConfigError::Identifier("workers.modules"));
        }
        let mut names = std::collections::BTreeSet::new();
        let mut modules = Vec::with_capacity(worker.modules.len());
        for module in &worker.modules {
            if !valid_module_name(&module.name) || !names.insert(&module.name) {
                return Err(ConfigError::Identifier("workers.modules.name"));
            }
            if !is_lower_hex(&module.sha256) {
                return Err(ConfigError::Digest("workers.modules.sha256"));
            }
            if !is_lower_hex(&module.source_sha256) {
                return Err(ConfigError::Digest("workers.modules.sourceSha256"));
            }
            check_text(&module.source, 1024, "workers.modules.source")?;
            if !valid_module_name(&module.dist) {
                return Err(ConfigError::Identifier("workers.modules.dist"));
            }
            modules.push(SystemModuleRef {
                name: module.name.clone(),
                digest: module.sha256.clone(),
            });
        }
        if !names.contains(&worker.main_module) {
            return Err(ConfigError::Identifier("workers.mainModule"));
        }
        system_workers.push(SystemWorkerRef {
            service_name: service_name.clone(),
            main_module: worker.main_module.clone(),
            modules,
            needs_binding_backend: worker.needs_binding_backend,
        });
    }

    let endpoint = |service: &str, field: &'static str| -> Result<ServiceEndpoint, ConfigError> {
        let worker = wire
            .workers
            .get(service)
            .ok_or(ConfigError::ServiceReference(field))?;
        Ok(ServiceEndpoint {
            service: service.to_owned(),
            entrypoint: worker.entrypoint.clone(),
        })
    };
    let facades = FacadeRefs {
        kv: endpoint(REQUIRED_FACADES[0], "facades.required")?,
        r2: endpoint(REQUIRED_FACADES[1], "facades.required")?,
        assets: endpoint(REQUIRED_FACADES[2], "facades.required")?,
        pg: endpoint(REQUIRED_FACADES[3], "facades.required")?,
        d1: endpoint(REQUIRED_FACADES[4], "facades.required")?,
        queue: endpoint(REQUIRED_FACADES[5], "facades.required")?,
        ratelimit: endpoint(REQUIRED_FACADES[6], "facades.required")?,
    };
    let egress = endpoint(EGRESS_SERVICE, "egress.required")?;
    let deny_outbound = endpoint(DENY_OUTBOUND_SERVICE, "denyOutbound.required")?;
    Ok(FacadeManifest {
        facades,
        egress,
        deny_outbound,
        system_workers,
    })
}
